import{z as i,x as l,o as r,c,q as s,j as t,D as e,d as o,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"原子操作的缓存实现","description":"","frontmatter":{"title":"原子操作的缓存实现","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/atomic-cache-impl.md","filePath":"cs/atomic-cache-impl.md","lastUpdated":1791413859000}'),d={name:"cs/atomic-cache-impl.md"};function B(p,a,h,m,_,C){const E=l("Mermaid");return r(),c("div",null,[a[2]||(a[2]=s('<h1 id="原子操作的缓存实现" tabindex="-1">原子操作的缓存实现 <a class="header-anchor" href="#原子操作的缓存实现" aria-label="Permalink to &quot;原子操作的缓存实现&quot;">​</a></h1><div class="epigraph"><p>CAS 与 fetch-and-add 在程序员看来是一条指令；在 cache 里它们是「拿到 M，在独占期间完成读改写，期间不让出该行」。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；McKenney 对 RMW 与缓存的论述 整理</footer></div><p><a href="/cs/false-sharing">上一课</a> 说明行上的争用极贵。真共享时还需要原子：计数器、锁字、<a href="/cs/lr-sc-cas">LR/SC 与 CAS</a> 在 ISA 对照里已经出现。本课不重讲伪共享填充。缺口是<strong>微结构：原子 RMW 如何挂在 MESI/MOESI 上，以及锁住 cache 行期间发生什么。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通 <code>add</code> 的 load 与 store 之间可以被他核的写插入。<a href="/cs/lsq-disambiguation">LSQ</a> 只保证本核。原子要求中间态对外不可见。缺口不是再加一个目录态，而是<strong>先升级到 M（或等价独占），在 L1 里完成 RMW，期间对该行的窥探延迟应答或重试。</strong></p><p><span class="marginnote">x86 <code>lock</code> 前缀历史上锁总线；当代是 cache lock：只锁该行。LR/SC：SC 时若行被作废则失败，不必全程占 M。</span></p><p><span class="marginnote">「RFO」（Read-for-Ownership）就是「我要独占这一行」的申请单：目录把其他核手里的副本统统作废，自己拿到唯一可写的 M 态。普通写也要走这一步；原子指令只是拿到 M 之后多霸占一会儿，把读改写闷在 L1 里做完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行原子：发出 Read-for-Ownership，等目录/窥探把 sharer 作废，行进 M。在 L1 对对齐地址做 ALU。提交前若被探询，要么延迟探询到 RMW 完成，要么放弃（SC 失败）。然后该行保持 M，或按协议共享。</p>',9)),(r(),t(n,null,{default:e(()=>[A(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ATO%5B%22%E5%8E%9F%E5%AD%90%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20RFO%5B%22%E6%B1%82%20M%20%2F%20%E7%8B%AC%E5%8D%A0%22%5D%0A%20%20RFO%20--%3E%20RMW%5B%22L1%20%E5%86%85%E8%AF%BB%E6%94%B9%E5%86%99%22%5D%0A%20%20RMW%20--%3E%20HOLD%5B%22%E6%9C%9F%E9%97%B4%E5%BB%B6%E8%BF%9F%E6%88%96%E6%8B%92%E7%BB%9D%E6%8E%A2%E8%AF%A2%22%5D%0A%20%20HOLD%20--%3E%20DONE%5B%22%E6%8F%90%E4%BA%A4%EF%BC%8C%E8%A1%8C%E4%BB%8D%20M%20%E6%88%96%E6%8C%89%E6%A8%A1%E5%9E%8B%E9%99%8D%E7%BA%A7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对齐：跨行原子要么禁止，要么锁两行——实现极痛，ISA 常要求自然对齐。争用：多个核打同一锁字 = 真共享 + 伪共享式颠簸，<a href="/cs/cache-partition-qos">分区</a> 救不了。指数退避在软件；硬件只保证这一次 RMW 的原子性。</p><p><span class="marginnote">数字实例：缓存行常为 64 字节。一个 8 字节变量若横骑在两行边界上，一次原子就得同时锁两行、让两套窥探逻辑协调；x86 对这种「拆行锁」要么退化成老式锁总线，要么在新机器上直接触发对齐异常——所以 ISA 要求自然对齐不是洁癖，是保命。</span></p><p>与 <a href="/cs/retire-precise-exception">退休</a>：原子通常要在 ROB 头附近执行或至少提交时行仍独占，否则精确异常难定义。这降低 MLP：原子像一个小栅栏。</p><p>同一次「要原子」，硬扛与让步两种策略的差别：</p>',5)),(r(),t(n,null,{default:e(()=>[A(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20LC%5B%22%E9%94%81%E5%89%8D%E7%BC%80%20CAS%EF%BC%9A%E7%A1%AC%E6%89%9B%22%5D%0A%20%20%20%20A1%5B%22%E5%8F%96%20M%20%E5%B9%B6%E9%94%81%E4%BD%8F%E8%AF%A5%E8%A1%8C%22%5D%20--%3E%20A2%5B%22%E5%A4%96%E6%9D%A5%E6%8E%A2%E8%AF%A2%E8%A2%AB%E6%8E%A8%E8%BF%9F%E5%88%B0%20RMW%20%E5%81%9A%E5%AE%8C%22%5D%0A%20%20end%0A%20%20subgraph%20LRSC%5B%22LR%20%2F%20SC%EF%BC%9A%E8%AE%A9%E6%AD%A5%22%5D%0A%20%20%20%20B1%5B%22LR%20%E5%8F%AA%E8%AE%B0%E4%B8%8B%E7%9B%91%E8%A7%86%E7%9A%84%E8%A1%8C%22%5D%20--%3E%20B2%5B%22%E8%A1%8C%E8%8B%A5%E8%A2%AB%E5%88%AB%E4%BA%BA%E4%BD%9C%E5%BA%9F%20SC%20%E7%9B%B4%E6%8E%A5%E5%A4%B1%E8%B4%A5%20%E8%BD%AF%E4%BB%B6%E9%87%8D%E8%AF%95%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 ISA 的原子清单写全。下一课 acquire/release 把「这一次 RMW」推广到「周围普通 load/store 能否重排」。事务内存则把多行原子合成一块，再下一课。</p><p><span class="marginnote">常见误区：初学者容易以为「原子指令和普通加法差不多快」。一次原子要走完整的 RFO 与窥探往返，多核争用同一行时每次都是一次全缓存级的交通管制，比本地普通读写慢几十倍——热点计数器要分片或先本地累积，而不是人人都抢着 <code>lock add</code>。</span></p><p>后课默认：原子 = 独占行上的 RMW。单地址原子还不够表达「解锁之前的写要对获取锁的人可见」——那是 acquire/release。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原子 RMW 先拿 M，在 L1 完成，探询被推迟或 SC 失败。</li><li>跨行与高争用是性能悬崖。</li><li>把周围访存的顺序钉到释放/获取语义，是下一课。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；McKenney。</li></ul>',6))])}const S=i(d,[["render",B]]);export{f as __pageData,S as default};
